    justify-content: flex-start;
    padding: var(--spacing-lg) 0;
}

.hero-bg {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: -1;
    background: #000; /* fallback */
}

.hero-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    opacity: 0.7; /* Create contrast for text */
}

.hero-content {
    max-width: 600px;
    color: var(--color-primary-inverse);
}

.hero h1 {
    font-size: clamp(2.5rem, 5vw, 4rem);
    line-height: 1.1;
    margin-bottom: var(--spacing-sm);
    font-weight: 800;
}

.hero p {
    font-size: 1.25rem;
    margin-bottom: var(--spacing-md);
    text-shadow: 0 1px 3px rgba(0,0,0,0.8);
}

/* ==========================================================================
   Product Grid
   ========================================================================== */
section {
    padding-top: var(--spacing-lg);
    padding-bottom: var(--spacing-lg);
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    margin-bottom: var(--spacing-md);
    flex-wrap: wrap;
    gap: var(--spacing-sm);
}

.section-header h2 {
    font-size: 2rem;
    font-weight: 700;
}

.view-all {
    font-weight: 600;
    color: var(--color-primary);
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
    gap: var(--spacing-md);
}

.product-card {
    display: flex;
    flex-direction: column;
    position: relative;
    group: product;
}

.product-image {
    background: var(--color-bg-alt);
    aspect-ratio: 3/4;
    overflow: hidden;
    border-radius: var(--radius-sm);
    margin-bottom: var(--spacing-sm);
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.4s ease;
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.product-title {
    font-size: 1rem;
    font-weight: 600;
    margin-bottom: 0.25rem;
}

.product-title a {
    text-decoration: none;
}

.product-title a::after {
    content: '';
    position: absolute;
    inset: 0;
}

.product-price {
    color: var(--color-text-muted);
    font-weight: 500;
}

/* ==========================================================================
   Deals Section
   ========================================================================== */
.deals {
    background-color: var(--color-primary);
    color: var(--color-primary-inverse);
}

.deals-wrapper {
    display: grid;
    grid-template-columns: 1fr;
    gap: var(--spacing-lg);
    align-items: center;
}

@media (min-width: 992px) {
    .deals-wrapper {
        grid-template-columns: 1fr 2fr;
    }
}

.deals-content h2 {
    font-size: 2.5rem;
    margin-bottom: var(--spacing-sm);
}

.deals-content p {
    font-size: 1.1rem;
    margin-bottom: var(--spacing-md);
    opacity: 0.9;
}

.deals-grid .product-title {
    color: var(--color-primary-inverse);
}

.deals-grid .product-price {
    color: rgba(255, 255, 255, 0.9);
}

.original-price {
    opacity: 0.7;
    margin-right: 0.5rem;
}

.sale-price {
    color: #ff9800; /* Contrast passing color against black */
    font-weight: 700;
}

.product-badge {
    position: absolute;
    top: 10px;
    left: 10px;
    background: var(--color-accent);
    color: white;
    padding: 0.25rem 0.5rem;
    font-size: 0.8rem;
    font-weight: bold;
    border-radius: var(--radius-sm);
    z-index: 10;
    text-transform: uppercase;
}

/* ==========================================================================
   Editorial Content
   ========================================================================== */
.editorial-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
}

@media (min-width: 768px) {
    .editorial-grid {
        grid-template-columns: repeat(2, 1fr);
    }
}

.editorial-card {
    display: flex;
    flex-direction: column;
}

.editorial-image {
    aspect-ratio: 16/9;
    overflow: hidden;
    border-radius: var(--radius-sm);
    margin-bottom: var(--spacing-sm);
}

.editorial-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.editorial-content h3 {
    font-size: 1.5rem;
    margin-bottom: 0.5rem;
}

.editorial-content h3 a {
    text-decoration: none;
}

.editorial-content h3 a:hover {
    text-decoration: underline;
}

.editorial-content p {
    color: var(--color-text-muted);
    margin-bottom: 1rem;
}

.read-more {
    font-weight: 600;
    text-transform: uppercase;
    font-size: 0.9rem;
    letter-spacing: 0.5px;
    color: var(--color-primary);
}

/* ==========================================================================
   Footer
   ========================================================================== */
.site-footer {
    background: var(--color-bg-alt);
    border-top: 1px solid var(--color-border);
    padding-top: var(--spacing-lg);
}

.footer-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: var(--spacing-lg);
    margin-bottom: var(--spacing-lg);
}

@media (min-width: 600px) {
    .footer-grid {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (min-width: 992px) {
    .footer-grid {
        grid-template-columns: 2fr 1fr 1fr 1.5fr;
    }
}

.brand-col .footer-logo {
    font-size: 1.5rem;
    font-weight: 800;
    text-transform: uppercase;
    margin-bottom: var(--spacing-sm);
}

.footer-col h3 {
    font-size: 1.1rem;
    margin-bottom: var(--spacing-sm);
    font-weight: 600;
}

.footer-links {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.footer-links a {
    color: var(--color-text-muted);
}

.footer-links a:hover {
    color: var(--color-primary);
}

.input-group {
    display: flex;
    gap: 0.5rem;
    margin-top: var(--spacing-sm);
}

.input-group input {
    flex: 1;
    padding: 0.5rem;
    border: 1px solid var(--color-border);
    border-radius: var(--radius-sm);
}

.input-group input:focus {
    border-color: var(--color-primary);
    outline: 2px solid var(--color-focus);
}

.footer-bottom {
    padding: var(--spacing-md) var(--spacing-sm);
    text-align: center;
    border-top: 1px solid var(--color-border);
    color: var(--color-text-muted);
    font-size: 0.9rem;
}

/* ==========================================================================
   Forced Colors adjustments
   ========================================================================== */
@media (forced-colors: active) {
    .btn {
        border: 2px solid ButtonBorder;
    }
    .hero-bg {
        display: none;
    }
    .hero-content {
        color: CanvasText;
    }
    .deals {
        background: Canvas;
        color: CanvasText;
        border: 2px solid CanvasText;
    }
    .deals-grid .product-title,
    .deals-grid .product-price {
        color: CanvasText;
    }
    .product-badge {
        border: 1px solid CanvasText;
    }
}

document.addEventListener('DOMContentLoaded', () => {
    // Mobile navigation toggle
    const menuToggle = document.querySelector('.menu-toggle');
    const mainNav = document.getElementById('main-nav');

    if (menuToggle && mainNav) {
        menuToggle.addEventListener('click', () => {
            const isExpanded = menuToggle.getAttribute('aria-expanded') === 'true';

            menuToggle.setAttribute('aria-expanded', !isExpanded);
            mainNav.classList.toggle('is-open');
        });
    }

    // Prevent default form submissions for demo purposes
    const forms = document.querySelectorAll('form');
    forms.forEach(form => {
        form.addEventListener('submit', (e) => {
            e.preventDefault();

            // Demo alert
            const isSearch = form.classList.contains('search-form');
            if (isSearch) {
                const searchInput = form.querySelector('input[type="search"]');
                if (searchInput && searchInput.value) {
                    alert(`Searching for: ${searchInput.value}`);
                    searchInput.value = '';
                }
            } else {
                const emailInput = form.querySelector('input[type="email"]');
                if (emailInput && emailInput.value) {
                    alert(`Subscribed with: ${emailInput.value}`);
                    emailInput.value = '';
                }
            }
        });
    });
});

